CREATE TABLE "public"."completed_lessons" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"      uuid,
  "lesson_id"    bigint,
  "completed_at" timestamp with time zone DEFAULT now(),
  CONSTRAINT "completed_lessons_pkey" PRIMARY KEY (id),
  CONSTRAINT "completed_lessons_user_id_lesson_id_key" UNIQUE (user_id, lesson_id),
  CONSTRAINT "completed_lessons_lesson_id_fkey" FOREIGN KEY (lesson_id) REFERENCES public.lessons(id) ON DELETE CASCADE,
  CONSTRAINT "completed_lessons_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id)
);

REVOKE ALL ON SEQUENCE "public"."completed_lessons_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."completed_lessons_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."completed_lessons_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."completed_lessons_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."completed_lessons_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."completed_lessons_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."completed_lessons_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."completed_lessons_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."completed_lessons" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."completed_lessons" TO "service_role";

REVOKE ALL ON TABLE "public"."completed_lessons" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."completed_lessons" TO "postgres";
